<div class="page-head"><div><span class="eyebrow">SUPER ADMIN · POLICY ENGINE</span><h1>Unified Governance Control Plane</h1><p>Every plan, feature flag, quota and override is stored in the database and evaluated at request time—no redeploy required.</p></div><span class="badge">Policy v<?=e($d['version']??1)?></span></div>
<section class="card"><div class="page-head"><div><h2>Testing Mode</h2><p class="muted">When enabled, all users receive testing access across the platform. Turn it off before production billing enforcement.</p></div><span class="badge"><?=policy_testing_mode()?'ON':'OFF'?></span></div><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="toggle_testing_mode"><label for="testing_mode">Testing Mode</label><select id="testing_mode" name="testing_mode"><option value="0" <?=!policy_testing_mode()?'selected':''?>>Off — enforce plan limits</option><option value="1" <?=policy_testing_mode()?'selected':''?>>On — unlimited testing access</option></select><button class="btn" type="submit">Save Testing Mode</button></form></section>
<section class="card"><div class="page-head"><div><h2>Dynamic 3-tier matrix</h2><p class="muted">Sliders and toggles below become the live source of truth for quotas and feature enforcement. For task, project, note, and AI quota fields, 0 means unlimited.</p></div></div><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="save_policy"><div style="overflow:auto"><table><thead><tr><th>Capability</th><th>Free</th><th>Basic</th><th>Premium</th></tr></thead><tbody><?php foreach($planKeys as $k):$sample=$d['plans']['free'][$k];?><tr><td><strong><?=e($labels[$k]??$k)?></strong><div class="muted"><code><?=e($k)?></code></div></td><?php foreach(['free','basic','premium'] as $p):$v=$d['plans'][$p][$k]??$sample;?><td><?php if(is_bool($sample)):?><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="plans[<?=$p?>][<?=$k?>]" value="1" <?=$v?'checked':''?>> <span><?=$v?'Enabled':'Locked'?></span></label><?php elseif($k==='url_redirect_mode'):?><select name="plans[<?=$p?>][<?=$k?>]"><?php foreach(['301','302','307'] as $m):?><option value="<?=$m?>" <?=$v===$m?'selected':''?>><?=$m?></option><?php endforeach;?></select><?php else:?><input type="range" class="policy-range" data-target="pv_<?=$p?>_<?=$k?>" value="<?=e($v)?>" min="0" max="<?=e(policy_range_max($k))?>" step="<?=($k==='file_storage_bytes'||$k==='file_max_bytes')?104857600:1?>" style="max-width:220px"><input id="pv_<?=$p?>_<?=$k?>" type="number" name="plans[<?=$p?>][<?=$k?>]" value="<?=e($v)?>" min="0" style="max-width:170px"><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><div class="actions" style="position:sticky;bottom:12px;z-index:5;background:var(--card,#fff);padding:12px;border:1px solid var(--line,#ddd);border-radius:10px;margin:12px 0"><strong>Dynamic 3-tier matrix</strong><span class="muted">Save quota and feature changes</span><button class="btn" type="submit">Save tier matrix</button></div><h3>Global feature flags / emergency kill switches</h3><div class="grid-main"><?php foreach($d['flags'] as $k=>$v):?><label><input type="checkbox" name="flags[<?=e($k)?>]" value="1" <?=$v?'checked':''?>> <?=e(ucwords(str_replace('_',' ',$k)))?></label><?php endforeach;?></div><h3>Global infrastructure limits</h3><div class="grid-main"><?php foreach(['redirect_rate_per_minute','api_rate_per_minute','api_rate_per_hour','upload_concurrency','upload_part_mb','download_speed_mbps','suspicious_ip_throttle_mbps','analytics_retention_days','file_log_retention_days','link_log_retention_days'] as $k):?><label><?=e(ucwords(str_replace('_',' ',$k)))?><input type="number" step="0.1" min="0" name="global[<?=$k?>]" value="<?=e($d['global'][$k])?>"></label><?php endforeach;?></div><h3>White-label</h3><div class="grid-main"><?php foreach(['name','logo','favicon','support_email','og_title','og_description','og_image'] as $k):?><label><?=e(ucwords(str_replace('_',' ',$k)))?><input name="branding[<?=$k?>]" value="<?=e($d['branding'][$k]??'')?>"></label><?php endforeach;?></div><button class="btn">Publish policy changes</button></form></section>
