<section class="card"><h2>Central registry</h2><form method="get"><input name="q" value="<?=e($search)?>" placeholder="Search link slug, destination, file token/name or username"><button class="btn">Search</button></form><?php if($search!==''):?><h3>Links</h3><div style="overflow:auto"><table><tr><th>Slug</th><th>User</th><th>Destination</th><th>Clicks</th><th>Actions</th></tr><?php foreach($links as $l):?><tr><td><?=e($l['slug'])?></td><td><?=e($l['username'])?></td><td><?=e(mb_strimwidth($l['destination_url'],0,60,'…'))?></td><td><?=number_format((int)$l['clicks'])?></td><td><form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="link_action"><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn small secondary" name="op" value="pause">Pause</button><button class="btn small danger" name="op" value="purge" onclick="return confirm('Purge link?')">Purge</button></form><form method="post" style="margin-top:6px"><?php echo csrf_field();?><input type="hidden" name="action" value="link_action"><input type="hidden" name="id" value="<?=$l['id']?>"><input name="destination" placeholder="New destination"><button class="btn small" name="op" value="remap">Remap</button></form></td></tr><?php endforeach;?></table></div><h3>Files</h3><div style="overflow:auto"><table><tr><th>File</th><th>User</th><th>Size</th><th>Status</th><th>Actions</th></tr><?php foreach($files as $f):?><tr><td><?=e($f['original_name'])?></td><td><?=e($f['username'])?></td><td><?=number_format((int)$f['size_bytes']/1048576,1)?> MB</td><td><?=e($f['status'])?></td><td><form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="file_action"><input type="hidden" name="id" value="<?=$f['id']?>"><button class="btn small secondary" name="op" value="quarantine">Quarantine</button><button class="btn small danger" name="op" value="delete" onclick="return confirm('Delete file record?')">Delete</button></form></td></tr><?php endforeach;?></table></div><?php endif;?></section>
<section class="grid-main"><div class="card"><h2>User governance</h2><p class="muted">Tier changes, bans, reset links, asset purge and secure support impersonation.</p><div style="overflow:auto"><table><tr><th>User</th><th>Plan</th><th>Status</th><th>Actions</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['username'])?><br><small><?=e($u['email'])?></small></td><td><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="user_plan"><input type="hidden" name="user_id" value="<?=$u['id']?>"><select name="plan" onchange="this.form.submit()"><option value="free" <?=$u['plan']==='free'?'selected':''?>>Free</option><option value="basic" <?=$u['plan']==='basic'?'selected':''?>>Basic</option><option value="premium" <?=$u['plan']==='premium'?'selected':''?>>Premium</option></select></form></td><td><?=e($u['status'])?></td><td><?php if((int)$u['id']!==$adminId):?><form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="user_status"><input type="hidden" name="user_id" value="<?=$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'disabled':'active'?>"><button class="btn small secondary"><?=$u['status']==='active'?'Ban':'Unban'?></button></form> <form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="user_reset"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="btn small secondary">Reset Password</button></form> <form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="impersonate"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="btn small secondary">Login As</button></form> <form method="post" style="display:inline" onsubmit="return confirm('Purge ALL links and files for this user?')"><?php echo csrf_field();?><input type="hidden" name="action" value="user_purge"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="btn small danger">Purge Assets</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>
<div class="card"><h2>Per-user overrides</h2><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="override"><div class="grid-main"><label>User<select name="user_id"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['username'])?></option><?php endforeach;?></select></label><label>Policy key<input name="policy_key" placeholder="file_storage_bytes / url_api"></label><label>Value<input name="policy_value" placeholder="53687091200 or true"></label><label>Expires<input type="datetime-local" name="expires_at"></label><label>Reason<input name="reason"></label></div><button class="btn">Grant / override</button></form><div style="overflow:auto"><table><tr><th>User</th><th>Key</th><th>Value</th><th></th></tr><?php foreach($overrides as $o):?><tr><td><?=e($o['username'])?></td><td><?=e($o['policy_key'])?></td><td><code><?=e($o['policy_value'])?></code></td><td><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="override_delete"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="btn small danger">Revoke</button></form></td></tr><?php endforeach;?></table></div></div></section>
<section class="grid-main"><div class="card"><h2>Developer infrastructure governance</h2><p class="muted">Global RPM/RPH controls are policy-backed. Revoke a user's link + file API tokens instantly; the user can generate fresh credentials only if their tier allows API access.</p><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="revoke_tokens"><label>User<select name="user_id"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['username'])?></option><?php endforeach;?></select></label><button class="btn danger">Revoke all tokens</button></form></div><div class="card"><h2>Failed webhook deliveries</h2><?php if(!$failedWebhooks):?><p class="muted">No failed deliveries recorded.</p><?php else:?><div style="overflow:auto"><table><tr><th>Scope</th><th>Event</th><th>Status</th><th>Time</th></tr><?php foreach($failedWebhooks as $w):?><tr><td><?=e($w['scope'])?></td><td><?=e($w['event_name'])?></td><td><?=e($w['status_code'])?></td><td><?=e($w['created_at'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div></section>
<section class="card"><h2>Immutable security audit</h2><p class="muted">Append-only administrative mutation trail: timestamp, admin, IP, action, before/after payload.</p><div style="overflow:auto"><table><tr><th>Time</th><th>Admin</th><th>Action</th><th>IP</th><th>Before</th><th>After</th></tr><?php foreach($audits as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['username']??'system')?></td><td><?=e($a['action'])?></td><td><?=e($a['ip_address'])?></td><td><code><?=e(mb_strimwidth((string)$a['before_json'],0,120,'…'))?></code></td><td><code><?=e(mb_strimwidth((string)$a['after_json'],0,120,'…'))?></code></td></tr><?php endforeach;?></table></div></section>
